<?php require_once 'includes/config.php'; $pdo=db(); $id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT p.*,c.name category_name,b.name brand_name FROM products p JOIN categories c ON c.id=p.category_id LEFT JOIN brands b ON b.id=p.brand_id WHERE p.id=? AND p.status=1');$st->execute([$id]);$p=$st->fetch();if(!$p){http_response_code(404);exit('Product not found.');}$pdo->prepare('UPDATE products SET views=views+1 WHERE id=?')->execute([$id]);
$gallery = [];
try {
    $gi = $pdo->prepare('SELECT image_path FROM product_images WHERE product_id=? ORDER BY sort_order,id');
    $gi->execute([$id]);
    $gallery = array_column($gi->fetchAll(), 'image_path');
} catch (Throwable $e) { $gallery = []; }
$gallery = array_values(array_unique(array_filter(array_merge([(string)$p['image']], $gallery))));
if (!$gallery) $gallery = ['https://images.unsplash.com/photo-1550749460-9b7c2f9d4b6d?auto=format&fit=crop&w=900&q=80'];
$u=user();if($_SERVER['REQUEST_METHOD']==='POST'&&$u){check_csrf();$rating=max(1,min(5,(int)$_POST['rating']));$comment=post_str('comment');$st=$pdo->prepare('INSERT INTO reviews(product_id,user_id,rating,comment) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),comment=VALUES(comment),status=1');$st->execute([$id,$u['id'],$rating,$comment]);$pdo->query("UPDATE products SET rating=(SELECT ROUND(AVG(rating),1) FROM reviews WHERE product_id=$id AND status=1) WHERE id=$id");flash('success','Your review was saved.');redirect('product.php?id='.$id);}$st=$pdo->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? AND r.status=1 ORDER BY r.created_at DESC');$st->execute([$id]);$reviews=$st->fetchAll();$title=$p['name'];require 'includes/header.php'; ?><div class="row g-5"><div class="col-lg-6"><div class="bg-white border rounded-4 p-3"><img id="productMainImage" src="<?=e(preg_match('#^https?://#i',(string)$gallery[0])?$gallery[0]:url($gallery[0]))?>" class="img-fluid w-100" style="max-height:520px;object-fit:contain" alt="<?=e($p['name'])?>"></div><?php if(count($gallery)>1): ?><div class="d-flex flex-wrap gap-2 mt-3"><?php foreach($gallery as $image): $imageUrl=preg_match('#^https?://#i',(string)$image)?$image:url($image); ?><button type="button" class="border rounded-3 p-1 bg-white" onclick="document.getElementById('productMainImage').src=this.dataset.image" data-image="<?=e($imageUrl)?>" aria-label="View product image"><img src="<?=e($imageUrl)?>" alt="" style="width:70px;height:70px;object-fit:contain"></button><?php endforeach; ?></div><?php endif; ?></div><div class="col-lg-6"><span class="eyebrow"><?=e($p['brand_name']?:'SHOPNEX')?></span><h1 class="fw-bold mt-2"><?=e($p['name'])?></h1><div class="rating mb-3">★★★★★ <span class="text-secondary"><?=e($p['rating'])?> / 5</span></div><p class="text-secondary"><?=e($p['description'])?></p><div class="display-6 fw-bold text-purple"><?=money($p['price'])?> <?php if($p['old_price']):?><del class="fs-6 text-secondary"><?=money($p['old_price'])?></del><?php endif;?></div><p class="mt-3"><?= $p['stock']>0?'<span class="badge bg-success">In stock</span>':'<span class="badge bg-danger">Out of stock</span>' ?></p><div class="d-flex gap-2"><form method="post" action="cart.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="btn btn-purple btn-lg" <?=$p['stock']<1?'disabled':''?>>Add to Cart</button></form><?php if($u):?><form method="post" action="wishlist.php"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><button class="btn btn-outline-purple btn-lg"><i class="bi bi-heart"></i> Wishlist</button></form><?php endif;?></div><div class="mt-4 panel p-3"><h6>Specifications</h6><?php $spec=json_decode($p['specifications']?:'{}',true)?:[];foreach($spec as $k=>$v):?><div class="d-flex justify-content-between border-bottom py-2"><span class="text-secondary"><?=e($k)?></span><strong><?=e($v)?></strong></div><?php endforeach;?></div></div></div><section class="mt-5"><h2 class="section-title">Reviews & ratings</h2><?php if($u):?><div class="panel p-4 mb-3"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="row g-2"><div class="col-md-2"><select class="form-select" name="rating"><option>5</option><option>4</option><option>3</option><option>2</option><option>1</option></select></div><div class="col-md-7"><input class="form-control" name="comment" placeholder="Write your review" required></div><div class="col-md-3"><button class="btn btn-purple w-100">Submit Review</button></div></div></form></div><?php else:?><p class="text-secondary">Login to write a review.</p><?php endif;?><?php foreach($reviews as $r):?><div class="panel p-3 mb-2"><div class="d-flex justify-content-between"><strong><?=e($r['name'])?></strong><span class="rating"><?=str_repeat('★',$r['rating'])?></span></div><p class="mb-0 mt-2 text-secondary"><?=e($r['comment'])?></p></div><?php endforeach;?></section><?php require 'includes/footer.php'; ?>